-- Restore non-pruned legacy BC tables and reference data still used by runtime code.
-- Safe for adopted legacy databases: tables are created only when absent and seed data uses INSERT IGNORE.

-- bcpEligibleCodes
CREATE TABLE IF NOT EXISTS `bcpEligibleCodes` (
  `Fee Item` varchar(255) DEFAULT NULL,
  `Section` varchar(255) DEFAULT NULL,
  `Fee Item Description` varchar(255) DEFAULT NULL
);

-- bill_recipients
CREATE TABLE IF NOT EXISTS bill_recipients (
  id int(10) unsigned NOT NULL auto_increment,
  name varchar(100) default NULL,
  address varchar(100) default NULL,
  city varchar(100) default NULL,
  province varchar(100) default NULL,
  postal varchar(6) default NULL,
  creationTime datetime NOT NULL default '0000-00-00 00:00:00',
  updateTime datetime NOT NULL default '0000-00-00 00:00:00',
  billingNo int(10) unsigned NOT NULL default '0',
  PRIMARY KEY  (id)
) ;

-- billing_cdm_service_codes
CREATE TABLE IF NOT EXISTS billing_cdm_service_codes (
  id int(10) unsigned NOT NULL auto_increment,
  cdmCode varchar(5) NOT NULL default '',
  serviceCode varchar(10) NOT NULL default '',
  PRIMARY KEY  (id)
) ;

-- billing_history
CREATE TABLE IF NOT EXISTS billing_history (
  id int(10) unsigned NOT NULL auto_increment,
  billingmaster_no int(10) unsigned NOT NULL default '0',
  billingstatus char(1) NOT NULL default '',
  creation_date datetime NOT NULL default '0000-00-00 00:00:00',
  practitioner_no varchar(10) NOT NULL DEFAULT '',
  billingtype varchar(4) NOT NULL DEFAULT '',
  seqNum varchar(10) NOT NULL DEFAULT '',
  amount varchar(7) NOT NULL DEFAULT '',
  amount_received varchar(7) NOT NULL DEFAULT '',
  payment_type_id int(10) unsigned NOT NULL DEFAULT 0,
  payee_practitioner_no int(10) unsigned NOT NULL DEFAULT 0,
  PRIMARY KEY (id)
) ROW_FORMAT=DYNAMIC;
CREATE INDEX IF NOT EXISTS `billing_history_master_payment_idx` ON `billing_history` (`billingmaster_no`, `payment_type_id`);

-- billing_msp_servicecode_times
CREATE TABLE IF NOT EXISTS billing_msp_servicecode_times (
  id int(10) unsigned NOT NULL auto_increment,
  billingservice_no varchar(10) NOT NULL default '0',
  timeRange tinyint(1) NOT NULL default '0',
  PRIMARY KEY (id)
);

-- billing_private_transactions
CREATE TABLE IF NOT EXISTS billing_private_transactions (
  id int(10) unsigned NOT NULL auto_increment,
  billingmaster_no int(10) unsigned NOT NULL default '0',
  amount_received double NOT NULL default '0',
  creation_date datetime NOT NULL default '0000-00-00 00:00:00',
  payment_type_id int(10) unsigned NOT NULL DEFAULT 0,
  PRIMARY KEY (id)
);
CREATE INDEX IF NOT EXISTS `billing_private_transactions_master_payment_idx` ON `billing_private_transactions` (`billingmaster_no`, `payment_type_id`);

-- billing_service_code_conditions
CREATE TABLE IF NOT EXISTS billing_service_code_conditions (
  id int(10) unsigned NOT NULL auto_increment,
  serviceCode varchar(10) NOT NULL default '',
  conditionCode varchar(10) NOT NULL default '',
  conditionInterval int(10) unsigned NOT NULL default '0',
  PRIMARY KEY  (id)
);

-- billing_trayfees
CREATE TABLE IF NOT EXISTS  billing_trayfees (
  id int(10) unsigned NOT NULL auto_increment,
  billingServiceNo varchar(10) NOT NULL default '0',
  billingServiceTrayNo varchar(10) NOT NULL default '0',
  PRIMARY KEY  (id)
);

-- billingstatus_types
CREATE TABLE IF NOT EXISTS billingstatus_types (
  billingstatus char(1) NOT NULL default '',
  displayName varchar(20) default '',
  displayNameExt varchar(50) default NULL,
  sortOrder int(10) unsigned NOT NULL default '0',
  PRIMARY KEY  (billingstatus)
);

-- billingtypes
CREATE TABLE IF NOT EXISTS billingtypes (
  billingtype varchar(10) NOT NULL default '',
  sortOrder int(10) unsigned NOT NULL default '0',
  PRIMARY KEY  (billingtype)
) ;

-- ctl_billingservice_age_rules
CREATE TABLE IF NOT EXISTS ctl_billingservice_age_rules (
  id int(11) NOT NULL auto_increment,
  minAge int(3) NOT NULL default '0',
  maxAge int(3) NOT NULL default '0',
  service_code varchar(10) NOT NULL default '',
  PRIMARY KEY  (id)
) ;

-- ctl_billingservice_sex_rules
CREATE TABLE IF NOT EXISTS ctl_billingservice_sex_rules (
  id int(11) NOT NULL auto_increment,
  gender char(1) NOT NULL default '',
  service_code varchar(10) NOT NULL default '',
  PRIMARY KEY  (id)
) ;

-- ctl_servicecodes_dxcodes
CREATE TABLE IF NOT EXISTS ctl_servicecodes_dxcodes (
  id int(10) unsigned NOT NULL auto_increment,
  service_code varchar(10) NOT NULL default '0',
  dxcode varchar(10) NOT NULL default '0',
  PRIMARY KEY  (id)
) ;

-- formBCAR2020
CREATE TABLE IF NOT EXISTS `formBCAR2020` (
                                              `id` int(10) NOT NULL AUTO_INCREMENT,
                                              `demographic_no` int(10) NOT NULL,
                                              `provider_no` varchar(6) NOT NULL,
                                              `formCreated` date DEFAULT NULL,
                                              `formEdited` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                                              UNIQUE KEY `id` (`id`)
);

-- formBCAR2020Data
CREATE TABLE IF NOT EXISTS `formBCAR2020Data` (
                                                  `form_id` int(10) NOT NULL,
                                                  `provider_no` varchar(6) NOT NULL,
                                                  `page_no` int(1) NOT NULL,
                                                  `field` varchar(255) NOT NULL,
                                                  `val` varchar(255) NOT NULL DEFAULT '',
                                                  `field_edited` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                                                  UNIQUE KEY `form_data` (`form_id`,`page_no`,`field`)
);

-- formBCAR2020Text
CREATE TABLE IF NOT EXISTS `formBCAR2020Text` (
                                                  `form_id` int(10) NOT NULL,
                                                  `provider_no` varchar(6) NOT NULL,
                                                  `page_no` int(1) NOT NULL,
                                                  `field` varchar(255) NOT NULL,
                                                  `val` text NOT NULL,
                                                  `field_edited` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                                                  UNIQUE KEY `form_data` (`form_id`,`page_no`,`field`)
);

