-- formECARES
CREATE TABLE IF NOT EXISTS `formECARES` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `demographic_no` int(11),
  `provider_no` varchar(11),
  `formCreated` datetime,
  `formEdited` timestamp,
  `formData` blob,
  `completed` tinyint(1),
  `completedDate` datetime,
  PRIMARY KEY (`id`)
);

